rss.channel:
{{ site.title }}
{{ site.url }}
{{ site.description|trim }}
{{ site.language }}

{% for u in updates[:30] %}


  {{ u.event or "Askaban update" }}{% if u.result %}: {{ u.result }}{% endif %}
  {{ site.url }}askaban/{{ u.id }}/
  {{ site.url }}askaban/{{ u.id }}/
  {{ u.when|rfc822 }}
  {{ u.text }}
  Askaban

{% endfor %}
{% for q in quizzes[:50] %}


  {{ q.title }}
  {{ site.url }}quiz/{{ q.slug }}/
  {{ site.url }}quiz/{{ q.slug }}/
  {{ q.date|rfc822 }}
  {{ q.summary }}
  {% for t in q.tags %}{{ t }}{% endfor %}


{% endfor %}
